## /Game/Stage 3D (visual) — 10 nodes, 21 wires
  The school in 3D behind everything: the stage, the dressing room, the car park, the dancers and the music. The three.js code (scripts/stage) draws into its own canvas inside this Group; the graph tells it the save and the screen state, and it reports the liv
  visual (indent = child of the line above):
    s3_host: Group "3D view" {position: "absolute", width: {"value":100,"unit":"%"}, height: {"value":100,"unit":"%"}, zIndex: 0, backgroundColor: "var(--scene-sky)", clip: true}
        comment: Fills the window behind the sheet and the bars. The canvas three.js makes is put in here and nowhere else.
  logic:
    s3_in: Component Inputs
        outputs: save: object, ui: object, words: array
    s3_out: Component Outputs
        inputs: stage: object
    s3_run: JavaScriptFunction "3D stage" {uses: "stage/stage,stage/world,stage/people,stage/play,stage/music,rules/data,rules/engine,rules/tunes,game/text"}
        inputs: host, save, words, ui
        outputs: stage: object, live: object, liveChanged: signal, cam: object, camChanged: signal, float: object, floatChanged: signal, act: string, arg: *, acted: signal
        run on value change OFF: host, save, ui, words
        functionScript:
          | const el = Inputs.host && Inputs.host.getDOMElement ? Inputs.host.getDOMElement() : null;
          | if (!el || !Inputs.save) return;
          | const T = await import(new URL('assets/vendor/three.module.js', document.baseURI).href);
          | const w = Scripts.text.words(Inputs.words || [], Inputs.save.lang || 'fr');
          | const size = { w: el.clientWidth || window.innerWidth, h: el.clientHeight || window.innerHeight };
          | // what the stage reports: the evening, the camera and the toolbar go to the screen state; a tap or the end of a
          | // run is a press like any other, sent on to the dispatcher
          | const ACT = { done: 'runDone', ui: 'stageUi', place: 'place', key: 'key', say: 'say' };
          | const emit = (kind, data) => {
          |   if (kind === 'live') { Outputs.live = data; Outputs.liveChanged(); return; }
          |   if (kind === 'cam') { Outputs.cam = data; Outputs.camChanged(); return; }
          |   if (kind === 'float') { Outputs.float = data; Outputs.floatChanged(); return; }
          |   Outputs.act = ACT[kind] || kind;
          |   Outputs.arg = data;
          |   Outputs.acted();
          | };
          | const stage = Scripts.stage.create({ T, window, document, size, save: Inputs.save, ui: Inputs.ui || {}, schoolName: (Inputs.save.school.name || '').trim() || w('school'), emit });
          | // the one element code puts on the page: three.js's own canvas, inside this Group
          | stage.canvas.style.width = '100%';
          | stage.canvas.style.height = '100%';
          | stage.canvas.style.display = 'block';
          | el.appendChild(stage.canvas);
          | const onResize = () => { size.w = el.clientWidth || window.innerWidth; size.h = el.clientHeight || window.innerHeight; stage.resize(); };
          | window.addEventListener('resize', onResize);
          | stage.unmount = () => { window.removeEventListener('resize', onResize); stage.destroy(); };
          | onResize();
          | Outputs.stage = stage;
        comment: No node draws three.js or synthesises music, so this stays code: reference/src world/people/play/music, as factories in scripts/stage. three.js itself is the vendored r177 in assets/vendor. It runs once, when the Group is on the page.
    s3_sync: JavaScriptFunction "Tell the stage" {uses: "game/text,rules/data"}
        inputs: stage, save, words, ui
        functionScript:
          | if (!Inputs.stage || !Inputs.save) return;
          | const w = Scripts.text.words(Inputs.words || [], Inputs.save.lang || 'fr');
          | Inputs.stage.sync(Inputs.save, Inputs.ui || {}, (Inputs.save.school.name || '').trim() || w('school'));
        comment: Whenever the save or the screen state changes, the 3D catches up (the coded game's G was shared; here the stage keeps its own copy).
    s3_bye: JavaScriptFunction "Stop the 3D when the page goes"
        inputs: stage
        run on value change OFF: stage
        functionScript:
          | if (Inputs.stage && Inputs.stage.unmount) Inputs.stage.unmount();
    s3_live: net.noodl.GlobalStore.Set "The evening so far" {storeName: "ui", key: "live"}
    s3_cam: net.noodl.GlobalStore.Set "The camera" {storeName: "ui", key: "cam"}
    s3_float: net.noodl.GlobalStore.Set "Where the toolbar goes" {storeName: "ui", key: "float"}
    s3_send: Event Sender "A tap or the end of a run" {channelName: "gala-act", payload: "act,arg"}
  wires (from.port -> to.port):
    s3_host.this -> s3_run.in-host
    s3_host.didMount -> s3_run.run
    s3_in.save -> s3_run.in-save
    s3_in.ui -> s3_run.in-ui
    s3_in.words -> s3_run.in-words
    s3_run.out-stage -> s3_sync.in-stage
    s3_in.save -> s3_sync.in-save
    s3_in.ui -> s3_sync.in-ui
    s3_in.words -> s3_sync.in-words
    s3_run.out-stage -> s3_bye.in-stage
    s3_host.willUnmount -> s3_bye.run
    s3_run.out-stage -> s3_out.stage
    s3_run.out-live -> s3_live.value
    s3_run.out-liveChanged -> s3_live.set
    s3_run.out-cam -> s3_cam.value
    s3_run.out-camChanged -> s3_cam.set
    s3_run.out-float -> s3_float.value
    s3_run.out-floatChanged -> s3_float.set
    s3_run.out-act -> s3_send.act
    s3_run.out-arg -> s3_send.arg
    s3_run.out-acted -> s3_send.sendEvent

## /Game/Toast (visual) — 6 nodes, 6 wires
  The little message at the bottom of the window ("Bought: Fairy ✨", "Not enough stars…", what just happened in the evening), shown for 2.6 seconds.
  visual (indent = child of the line above):
    to_root: Group "Toast" {position: "absolute", alignX: "center", alignY: "bottom", marginBottom: "var(--space-6)", sizeMode: "contentSize", maxWidth: {"value":520,"unit":"px"}, backgroundColor: "var(--surface)", borderStyle: "solid", borderWidth: "var(--bor
      to_text: Text {fontWeight: "var(--font-bold)", textAlignX: "center"}
  logic:
    to_sub: net.noodl.GlobalStore.Subscribe {storeName: "ui", keys: "toast"}
    to_fn: JavaScriptFunction "A new toast"
        inputs: toast
        outputs: text: string, show: signal
        functionScript:
          | const t = Inputs.toast;
          | if (!t || !t.text) return;
          | Outputs.text = t.text;
          | Outputs.show();
    to_on: Switch "Toast showing"
    to_timer: Timer "2.6 seconds" {duration: 2600}
  wires (from.port -> to.port):
    to_sub.value -> to_fn.in-toast
    to_fn.out-text -> to_text.text
    to_fn.out-show -> to_on.on
    to_fn.out-show -> to_timer.restart
    to_timer.timerFinished -> to_on.off
    to_on.state -> to_root.mounted

## /Game/Top Bar (visual) — 18 nodes, 16 wires
  The bar over the 3D view: the school's name, the season (tap it to read the season's letter again), the stars, the clock of the live evening, the music switch, the language switch, and the door to the grown-ups' settings.
  places: /UI/Chip
  visual (indent = child of the line above):
    tb_root-2: Group "Top bar" {position: "absolute", alignX: "left", alignY: "top", flexDirection: "row", flexWrap: "wrap", alignItems: "center", sizeMode: "contentSize", maxWidth: {"value":60,"unit":"vw"}, columnGap: "var(--space-2)", rowGap: "var(--space-2)
      tb_brand: Text "School name" {fontFamily: "var(--font-script)", fontSize: {"value":26,"unit":"px"}, color: "var(--primary)", styleCss: "text-shadow: 0 2px 0 rgba(0,0,0,.45); white-space: nowrap;"}
      tb_season: UI/Chip "Season (opens the season's letter)"
      tb_stars: UI/Chip "Stars"
      tb_day: UI/Chip "The live evening's clock"
      tb_sound: UI/Chip "Music on/off"
      tb_lang: UI/Chip "FR / EN"
      tb_grown: UI/Chip "Grown-ups" {label: "⚙︎"}
  logic:
    tb_noDay: Inverter "No clock outside a run"
    tb_saveSub: net.noodl.GlobalStore.Subscribe {storeName: "gala", keys: "save"}
    tb_uiSub: net.noodl.GlobalStore.Subscribe {storeName: "ui", keys: "ui"}
    tb_liveSub: net.noodl.GlobalStore.Subscribe {storeName: "ui", keys: "live"}
    tb_words: Variable2 "words (shared on purpose)" {name: "words"}
    tb_view: JavaScriptFunction "What the bar says" {uses: "view/frame,view/common,game/text,rules/data,rules/engine"}
        inputs: save, words, ui, live
        outputs: brand, season, stars, day, sound, lang
        functionScript:
          | if (!Inputs.save || !Inputs.save.school) return;
          | const w = Scripts.text.words(Inputs.words || [], Inputs.save.lang || 'fr');
          | const t = Scripts.frame.top(Inputs.save, { ...(Inputs.ui || {}), live: Inputs.live }, w);
          | Outputs.brand = t.brand;
          | Outputs.season = t.season;
          | Outputs.stars = t.stars;
          | Outputs.day = t.day;
          | Outputs.sound = t.sound;
          | Outputs.lang = t.lang;
    tb_sendIntro: Event Sender {channelName: "gala-act", payload: "act,arg", act: "intro"}
    tb_sendSound: Event Sender {channelName: "gala-act", payload: "act,arg", act: "sound"}
    tb_sendLang: Event Sender {channelName: "gala-act", payload: "act,arg", act: "lang"}
    tb_goGrown: RouterNavigate "To the grown-ups' settings" {target: "/Pages/Grownups"}
  wires (from.port -> to.port):
    tb_saveSub.value -> tb_view.in-save
    tb_uiSub.value -> tb_view.in-ui
    tb_liveSub.value -> tb_view.in-live
    tb_words.value -> tb_view.in-words
    tb_view.out-brand -> tb_brand.text
    tb_view.out-season -> tb_season.label
    tb_view.out-stars -> tb_stars.label
    tb_view.out-day -> tb_day.label
    tb_view.out-day -> tb_noDay.value
    tb_noDay.result -> tb_day.hidden
    tb_view.out-sound -> tb_sound.label
    tb_view.out-lang -> tb_lang.label
    tb_season.click -> tb_sendIntro.sendEvent
    tb_sound.click -> tb_sendSound.sendEvent
    tb_lang.click -> tb_sendLang.sendEvent
    tb_grown.click -> tb_goGrown.navigate

## /Pages/Game (page) — 14 nodes, 5 wires
  The game: the 3D school fills the window; over it the top bar, the camera bar, the side sheet (the preparations, the live evening, the verdicts), the toast and the season's letter. Drawn once the start-up has opened the save.
  places: /Game/Camera Bar, /Game/Dispatcher, /Game/Furniture Toolbar, /Game/Season Letter, /Game/Sheet, /Game/Stage 3D, /Game/Toast, /Game/Top Bar
  visual (indent = child of the line above):
    gm_page: Page {title: "Le Gala de danse", urlPath: "game"}
      gm_root: Group "The window" {position: "relative", width: {"value":100,"unit":"vw"}, height: {"value":100,"unit":"vh"}, clip: true, backgroundColor: "var(--background)", mounted: false}
          comment: Mounted only when the start-up has laid the grown-ups' changes over the game and opened the save, so nothing draws from the wrong tables.
        gm_stage: Game/Stage 3D
        gm_top: Game/Top Bar
        gm_cam: Game/Camera Bar
        gm_sheet: Game/Sheet
        gm_float: Game/Furniture Toolbar
        gm_toast: Game/Toast
        gm_letter: Game/Season Letter
  logic:
    gm_ready: Variable2 "ready" {name: "ready"}
    gm_save: net.noodl.GlobalStore.Subscribe {storeName: "gala", keys: "save"}
    gm_ui: net.noodl.GlobalStore.Subscribe {storeName: "ui", keys: "ui"}
    gm_words: Variable2 "words (shared on purpose)" {name: "words"}
    gm_dispatch: Game/Dispatcher
  wires (from.port -> to.port):
    gm_ready.value -> gm_root.mounted
    gm_save.value -> gm_stage.save
    gm_ui.value -> gm_stage.ui
    gm_words.value -> gm_stage.words
    gm_stage.stage -> gm_dispatch.stage

