    case 'ab': {
      if (arg === 'B' && !np.B) np.B = np.A.map((p) => ({ ...p }));
      return { save, ui: { ...ui0, editB: arg === 'B' } };
    }
    case 'block': return { ui: { ...ui, selBlock: { ...ui.selBlock, [id]: arg }, selMove: null } };
